package com.example.mxb.command;

import com.example.mxb.MxbPlugin;
import com.example.mxb.config.CheatType;
import com.example.mxb.data.Ban;
import com.example.mxb.gui.CheatTypeGUI;
import com.example.mxb.util.TimeUtil;
import org.bukkit.Bukkit;
import org.bukkit.OfflinePlayer;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.jetbrains.annotations.NotNull;

import java.util.ArrayList;
import java.util.List;

public class MxbCommand implements CommandExecutor, TabCompleter {

    private final MxbPlugin plugin;

        public MxbCommand(MxbPlugin plugin) {
                this.plugin = plugin;
                    }

                        @Override
                            public boolean onCommand(@NotNull CommandSender sender, @NotNull Command command,
                                                         @NotNull String label, @NotNull String[] args) {

                                                                 if (!(sender instanceof Player player)) {
                                                                             sender.sendMessage("该命令只能由玩家执行");
                                                                                         return true;
                                                                                                 }

                                                                                                         if (!player.hasPermission("mxb.admin") && !player.isOp()) {
                                                                                                                     player.sendMessage(TimeUtil.color(plugin.getConfig().getString(
                                                                                                                                         "messages.no-permission", "&c你没有权限执行此操作")));
                                                                                                                                                     return true;
                                                                                                                                                             }

                                                                                                                                                                     if (args.length == 0) {
                                                                                                                                                                                 new CheatTypeGUI(plugin).open(player);
                                                                                                                                                                                             return true;
                                                                                                                                                                                                     }

                                                                                                                                                                                                             switch (args[0].toLowerCase()) {
                                                                                                                                                                                                                         case "unban" -> {
                                                                                                                                                                                                                                         if (args.length < 2) { player.sendMessage(TimeUtil.color("&c用法: /mxb unban <玩家>")); return true; }
                                                                                                                                                                                                                                                         handleUnban(player, args[1]);
                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                 case "history" -> {
                                                                                                                                                                                                                                                                                                 if (args.length < 2) { player.sendMessage(TimeUtil.color("&c用法: /mxb history <玩家>")); return true; }
                                                                                                                                                                                                                                                                                                                 handleHistory(player, args[1]);
                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                         case "clearwarn" -> {
                                                                                                                                                                                                                                                                                                                                                         if (args.length < 3) {
                                                                                                                                                                                                                                                                                                                                                                             player.sendMessage(TimeUtil.color("&c用法: /mxb clearwarn <玩家> <作弊类型>"));
                                                                                                                                                                                                                                                                                                                                                                                                 return true;
                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                 handleClearWarn(player, args[1], args[2]);
                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                         case "help" -> sendHelp(player);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                     default -> new CheatTypeGUI(plugin).open(player);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             private void handleUnban(Player player, String targetName) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     OfflinePlayer target = Bukkit.getOfflinePlayer(targetName);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (plugin.getBanManager().getActiveBan(target.getUniqueId()) == null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         player.sendMessage(TimeUtil.color(plugin.getConfig().getString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             "messages.not-banned", "&c该玩家当前没有被封禁")));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         plugin.getBanManager().unban(target.getUniqueId(), player);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 player.sendMessage(TimeUtil.color(plugin.getConfig().getString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 "messages.unban-success", "&a已解封 &e%player%")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .replace("%player%", targetName)));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         Bukkit.broadcastMessage(TimeUtil.color(plugin.getConfig().getString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         "messages.unban-broadcast", "&e%player% &7已被 &e%operator% &7解封")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .replace("%player%", targetName)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .replace("%operator%", player.getName())));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 private void handleHistory(Player player, String targetName) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         OfflinePlayer target = Bukkit.getOfflinePlayer(targetName);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 List<Ban> bans = plugin.getBanManager().getHistory(target.getUniqueId());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (bans.isEmpty()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     player.sendMessage(TimeUtil.color(plugin.getConfig().getString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         "messages.history-empty", "&c该玩家没有封禁记录")));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     player.sendMessage(TimeUtil.color(plugin.getConfig().getString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     "messages.history-header", "&6===== &e%player% &6的封禁记录 =====")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .replace("%player%", targetName)));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             String entry = plugin.getConfig().getString("messages.history-entry",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             "&7#%id% %state% &7| 类型: &f%cheat_type% &7| 原因: &f%reason% &7| 开始: &f%start% &7| 结束: &f%end% &7| 操作: &f%operator%");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     for (Ban b : bans) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 String state = b.isActive() ? "&c封禁中" : "&a已解封";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             String end = b.getEndTime() < 0 ? "永久" : TimeUtil.formatDate(b.getEndTime());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         player.sendMessage(TimeUtil.color(entry
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .replace("%id%", String.valueOf(b.getId()))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .replace("%state%", state)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .replace("%cheat_type%", b.getCheatTypeName() == null ? b.getCheatType() : b.getCheatTypeName())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .replace("%reason%", b.getReason() == null ? "" : b.getReason())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .replace("%start%", TimeUtil.formatDate(b.getStartTime()))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .replace("%end%", end)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .replace("%operator%", b.getOperatorName() == null ? "" : b.getOperatorName())));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     private void handleClearWarn(Player player, String targetName, String typeId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             CheatType type = plugin.getTypeConfig().getType(typeId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (type == null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 player.sendMessage(TimeUtil.color(plugin.getConfig().getString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     "messages.type-not-found", "&c找不到该作弊类型")));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 OfflinePlayer target = Bukkit.getOfflinePlayer(targetName);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         boolean ok = plugin.getWarnManager().clearCount(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         target.getUniqueId().toString(), type.getId());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 String msgKey = ok ? "messages.clearwarn-success" : "messages.clearwarn-none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         String def = ok ? "&a已清除 &e%player% &a的 &e%cheat_type% &a警告次数"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 : "&c该玩家该类型本来就没有警告记录";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         player.sendMessage(TimeUtil.color(plugin.getConfig().getString(msgKey, def)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .replace("%player%", targetName)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .replace("%cheat_type%", type.getName())));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 private void sendHelp(Player player) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         player.sendMessage(TimeUtil.color("&6===== Mxb 帮助 ====="));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 player.sendMessage(TimeUtil.color("&e/mxb &7- 打开封禁菜单"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         player.sendMessage(TimeUtil.color("&e/mxb unban <玩家> &7- 解封玩家"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 player.sendMessage(TimeUtil.color("&e/mxb history <玩家> &7- 查看封禁历史"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         player.sendMessage(TimeUtil.color("&e/mxb clearwarn <玩家> <作弊类型> &7- 清除某类型警告次数"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 @Override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     public List<String> onTabComplete(@NotNull CommandSender sender, @NotNull Command command,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           @NotNull String alias, @NotNull String[] args) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   List<String> list = new ArrayList<>();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (args.length == 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       for (String s : List.of("unban", "history", "clearwarn", "help")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (s.startsWith(args[0].toLowerCase())) list.add(s);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           } else if (args.length == 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           && (args[0].equalsIgnoreCase("unban")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            || args[0].equalsIgnoreCase("history")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             || args[0].equalsIgnoreCase("clearwarn"))) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         for (Player p : Bukkit.getOnlinePlayers()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (p.getName().toLowerCase().startsWith(args[1].toLowerCase())) list.add(p.getName());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             } else if (args.length == 3 && args[0].equalsIgnoreCase("clearwarn")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         for (CheatType t : plugin.getTypeConfig().getTypes()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (t.getId().toLowerCase().startsWith(args[2].toLowerCase())) list.add(t.getId());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     return list;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }